css:
@import url("https://fonts.googleapis.com/css2?family=Cormorant+Garamond:ital,wght@0,500;0,600;1,500&family=Nunito+Sans:opsz,wght@6..12,400;6..12,600;6..12,700&display=swap");
:root{--pist:#E7EFE3;--pist-2:#F3F7F1;--forest:#2F4A3A;--forest-2:#46654F;--rose:#D9897A;--rose-l:#F7E3DE;--text:#2B3530;--muted:#66736B;--line:#DCE5D8;
--serif:"Cormorant Garamond",Georgia,serif;--sans:"Nunito Sans",system-ui,-apple-system,"Segoe UI",sans-serif;--wrap:1200px}
*,*::before,*::after{box-sizing:border-box}html{scroll-behavior:smooth}
body{margin:0;font-family:var(--sans);font-size:17px;line-height:1.65;color:var(--text);background:#fff;-webkit-font-smoothing:antialiased}
img{max-width:100%;height:auto;display:block}a{color:inherit}p{margin:0 0 1em}
h1,h2,h3{font-family:var(--serif);font-weight:600;margin:0;line-height:1.02;color:var(--forest)}
.wrap{max-width:var(--wrap);margin:0 auto;padding:0 22px}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--rose-l);padding:10px;z-index:99}
:focus-visible{outline:2px solid var(--rose);outline-offset:3px;border-radius:6px}
.promo{background:var(--forest);color:var(--pist);text-align:center;font-size:14px;padding:8px}
.site-header{position:sticky;top:0;z-index:40;background:rgba(255,255,255,.95);border-bottom:1px solid var(--line)}
.nav{display:flex;align-items:center;justify-content:space-between;height:72px}
.logo{font-family:var(--serif);font-size:32px;font-weight:600;text-decoration:none;color:var(--forest);font-style:italic}
.menu{display:flex;gap:26px;list-style:none;margin:0;padding:0}.menu a{text-decoration:none;font-weight:600}.menu a:hover{color:var(--rose)}
.bag{background:var(--pist);border-radius:999px;padding:8px 16px;font-weight:700;text-decoration:none;color:var(--forest)}
.burger{display:none;background:none;border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}.burger span{display:block;width:20px;height:2px;background:var(--forest);margin:4px 0}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 26px;border-radius:999px;font-weight:700;text-decoration:none;border:1.5px solid transparent;font-family:var(--sans);font-size:16px;cursor:pointer}
.btn-f{background:var(--forest);color:#fff}.btn-f:hover{background:var(--forest-2)}
.btn-o{border-color:var(--forest);color:var(--forest);background:transparent}
.hero{background:var(--pist);padding:0;overflow:hidden}
.hero-grid{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:center;min-height:600px}
.hero h1{font-size:clamp(52px,7vw,100px)}
.hero h1 em{color:var(--rose)}
.hero .lead{font-size:20px;color:var(--muted);max-width:42ch;margin:22px 0 30px}
.actions{display:flex;gap:12px;flex-wrap:wrap}
.clean{display:flex;gap:16px;flex-wrap:wrap;margin-top:30px;font-size:14px;font-weight:700;color:var(--forest-2);list-style:none;padding:0}.clean li::before{content:"✓ ";color:var(--rose)}
.hero-img{position:relative;height:100%;min-height:520px}
.hero-img img{position:absolute;right:0;top:40px;bottom:40px;width:92%;height:calc(100% - 80px);object-fit:cover;border-radius:200px 200px 24px 24px}
.hero-img .pill{position:absolute;left:0;bottom:80px;background:#fff;border-radius:18px;padding:14px 18px;box-shadow:0 20px 40px -20px rgba(47,74,58,.5);font-size:14px}.pill b{display:block;font-family:var(--serif);font-size:28px;color:var(--forest)}
section{padding:90px 0}
.head{text-align:center;max-width:700px;margin:0 auto 46px}.head h2{font-size:clamp(40px,5vw,64px)}.head p{color:var(--muted);font-size:18px;margin-top:12px}
.quiz{background:var(--rose-l);border-radius:32px;padding:44px;max-width:900px;margin:0 auto}
.steps{display:flex;gap:8px;justify-content:center;margin-bottom:24px}.steps i{width:40px;height:5px;border-radius:3px;background:#EBC6BE}.steps i.on{background:var(--rose)}
.q{display:none;text-align:center}.q.on{display:block}
.q h3{font-size:36px;margin-bottom:20px}
.opts{display:flex;gap:12px;justify-content:center;flex-wrap:wrap}
.opts button{background:#fff;border:1.5px solid #EBC6BE;border-radius:999px;padding:12px 22px;font:inherit;font-weight:700;cursor:pointer;color:var(--forest)}
.opts button:hover{border-color:var(--rose)}
.result{display:none}.result.on{display:block}
.result h3{font-size:36px;text-align:center;margin-bottom:6px}.result>p{text-align:center;color:var(--muted)}
.routine{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:24px}
.routine div{background:#fff;border-radius:20px;padding:18px;text-align:center}
.routine small{color:var(--rose);font-weight:700}.routine b{display:block;font-family:var(--serif);font-size:24px;color:var(--forest);margin:6px 0}
.routine img{border-radius:14px;aspect-ratio:1/1;object-fit:cover;width:100%;margin-bottom:10px}
.again{background:none;border:0;color:var(--forest);text-decoration:underline;cursor:pointer;font:inherit;display:block;margin:20px auto 0}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.p figure{margin:0 0 12px;border-radius:24px;overflow:hidden;background:var(--pist-2);aspect-ratio:4/5;position:relative}
.p img{width:100%;height:100%;object-fit:cover}
.p .tag{position:absolute;top:12px;left:12px;background:#fff;border-radius:999px;font-size:12px;font-weight:700;padding:3px 10px;color:var(--forest)}
.p small{color:var(--rose);font-weight:700;font-size:13px}
.p h3{font-size:24px;margin:2px 0}
.p p{color:var(--muted);font-size:15px;margin:0 0 10px}
.p .row{display:flex;justify-content:space-between;align-items:center}
.p .pr{font-weight:700;font-size:18px}
.p button{background:var(--forest);color:#fff;border:0;border-radius:999px;padding:9px 16px;font:inherit;font-weight:700;font-size:14px;cursor:pointer}
.ingr{background:var(--forest);color:#C9D8CE}
.ingr .head h2{color:#fff}.ingr .head p{color:#A9BDB0}
.ig{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.ig div{border:1px solid var(--forest-2);border-radius:20px;padding:24px}
.ig b{font-family:var(--serif);font-size:30px;color:#fff;display:block;margin-bottom:6px}.ig p{margin:0;font-size:15px}
.free{display:flex;gap:10px;flex-wrap:wrap;justify-content:center;margin-top:36px}
.free span{border:1px solid var(--forest-2);border-radius:999px;padding:6px 14px;font-size:14px}
.story{display:grid;grid-template-columns:1fr 1fr;gap:56px;align-items:center}
.story img{border-radius:24px;aspect-ratio:4/5;object-fit:cover;width:100%}
.story h2{font-size:clamp(38px,4.6vw,58px);margin-bottom:16px}.story p{color:var(--muted);font-size:18px}
.revs{background:var(--pist-2)}
.rv-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}
.rv{background:#fff;border-radius:22px;padding:26px;margin:0}
.rv .st{color:var(--rose);letter-spacing:3px}.rv p{font-family:var(--serif);font-size:24px;line-height:1.3;color:var(--forest);margin:10px 0}
.rv cite{font-style:normal;font-size:14px;color:var(--muted)}.rv cite b{color:var(--text)}
.faq{max-width:800px;margin:0 auto}
.faq details{border-bottom:1px solid var(--line);padding:18px 0}
.faq summary{list-style:none;cursor:pointer;font-weight:700;font-size:19px;display:flex;justify-content:space-between;gap:16px;color:var(--forest)}
.faq summary::-webkit-details-marker{display:none}.faq summary::after{content:"+";color:var(--rose);font-size:24px;line-height:1}.faq details[open] summary::after{content:"−"}
.faq details p{margin:10px 0 0;color:var(--muted)}
footer{background:var(--pist);padding:50px 0 26px;font-size:15px;color:var(--muted)}
.foot{display:grid;grid-template-columns:1.4fr repeat(3,1fr);gap:30px;margin-bottom:30px}
footer h3{font-family:var(--sans);font-size:15px;font-weight:700;color:var(--forest);margin-bottom:10px}footer ul{list-style:none;padding:0;margin:0}footer li{margin-bottom:6px}footer a{text-decoration:none}footer a:hover{color:var(--forest)}
.legal{border-top:1px solid var(--line);padding-top:16px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap}
.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--forest);color:#fff;padding:12px 22px;border-radius:999px;font-weight:600;transition:transform .3s;z-index:70}.toast.show{transform:translate(-50%,0)}
@media (max-width:1000px){.menu{display:none}.burger{display:block}.menu.open{display:flex;flex-direction:column;position:absolute;top:72px;left:0;right:0;background:#fff;padding:20px;border-bottom:1px solid var(--line);gap:14px}
.hero-grid,.story{grid-template-columns:1fr}.hero-grid{padding-top:50px}.grid,.ig{grid-template-columns:1fr 1fr}.rv-grid{grid-template-columns:1fr}.foot{grid-template-columns:1fr 1fr}}
@media (max-width:560px){section{padding:64px 0}.quiz{padding:26px 18px}.routine{grid-template-columns:1fr}.grid,.ig{grid-template-columns:1fr}.hero-img .pill{display:none}}

.toast{visibility:hidden}.toast.show{visibility:visible}

javascript:
const P={clean:["Gentle cream cleanser","Step 1 · Cleanse",18,"1631729371254-42c2892f0e6e","Removes make-up without stripping skin."],
calm:["Niacinamide calm serum","Step 2 · Treat",32,"1617897903246-719242758050","10% niacinamide for redness and pores."],
clear:["Clear skin BHA serum","Step 2 · Treat",29,"1612817288484-6f916006741a","Gentle salicylic acid for breakouts."],
glow:["Vitamin C glow drops","Step 2 · Treat",34,"1617897903246-719242758050","Brightens dull, tired-looking skin."],
rich:["Barrier repair cream","Step 3 · Moisturise",28,"1612817288484-6f916006741a","Ceramides for dry, tight skin."],
light:["Oil-free gel cream","Step 3 · Moisturise",26,"1631729371254-42c2892f0e6e","Light hydration that won't clog pores."],
spf:["Mineral SPF 50","Morning · Protect",30,"1596462502278-27bfdc403348","No white cast, works under make-up."]};
const bag={n:0};const $=id=>document.getElementById(id);
function toast(t){const x=$('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function add(k,q=1){bag.n+=q;$('bc').textContent=bag.n}
$('grid').innerHTML=['clean','calm','clear','spf'].map(k=>[k,P[k]]).map(([k,p],i)=>`<article class="p"><figure><img src="https://images.unsplash.com/photo-${p[3]}?w=500&h=625&q=75&auto=format&fit=crop" alt="${p[0]}" width="500" height="625" loading="lazy">${i===0?'<span class="tag">Bestseller</span>':''}</figure><small>${p[1]}</small><h3>${p[0]}</h3><p>${p[4]}</p><div class="row"><span class="pr">$${p[2]}</span><button type="button" data-k="${k}">Add to bag</button></div></article>`).join('');
$('grid').addEventListener('click',e=>{const b=e.target.closest('[data-k]');if(!b)return;add(b.dataset.k);toast(P[b.dataset.k][0]+' added to your bag')});
const ans={},qs=[...document.querySelectorAll('.q')],dots=[...document.querySelectorAll('.steps i')];let step=0,picked=[];
qs.forEach((q,i)=>q.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;ans[q.dataset.k]=b.dataset.v;q.classList.remove('on');step=i+1;dots.forEach((d,j)=>d.classList.toggle('on',j<=step));
 if(step<qs.length)qs[step].classList.add('on');else show()}));
function show(){const treat={redness:'calm',spots:'clear',lines:'glow',dull:'glow'}[ans.concern],moist=(ans.type==='dry'||ans.type==='normal')?'rich':'light';
picked=ans.time==='2'?['clean',moist,'spf']:['clean',treat,moist];
const names={dry:'dry',oily:'oily',combo:'combination',normal:'balanced'};
$('rtitle').textContent='Your routine for '+names[ans.type]+' skin';$('rtext').textContent=ans.time==='2'?'Three quick steps you can do in two minutes.':'Three steps with a targeted treatment for '+({redness:'redness',spots:'breakouts',lines:'fine lines',dull:'dull skin'}[ans.concern])+'.';
$('routine').innerHTML=picked.map(k=>`<div><img src="https://images.unsplash.com/photo-${P[k][3]}?w=300&h=300&q=70&auto=format&fit=crop" alt="" width="300" height="300"><small>${P[k][1]}</small><b>${P[k][0]}</b>$${P[k][2]}</div>`).join('');
$('result').classList.add('on')}
$('addAll').addEventListener('click',()=>{add(null,3);toast('Your 3-step routine is in your bag')});
$('again').addEventListener('click',()=>{$('result').classList.remove('on');step=0;qs[0].classList.add('on');dots.forEach((d,j)=>d.classList.toggle('on',j===0))});
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
